import type { ArchiveScope, IsoTimestamp, SoftDeletable } from "@/types/common";
import { toIsoTimestamp } from "@/types/common";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/**
 * Soft-delete conventions.
 *
 * Issues, projects and comments are archived rather than removed — they get an
 * `archived_at` timestamp. Repositories must express "live rows only" through
 * these helpers so the predicate stays in one place; a raw
 * `isNull(table.archivedAt)` sprinkled through the data layer is exactly the
 * drift this module prevents.
 *
 * An archived issue sits in the trash for the plan's `retentionDays`: until
 * then it can be restored, afterwards it is expired and the retention sweep
 * deletes it for good.
 */

export function isArchived(row: SoftDeletable): boolean {
  return row.archivedAt !== null;
}

export function isLive(row: SoftDeletable): boolean {
  return row.archivedAt === null;
}

/**
 * The instant a row archived at or before has outlived `retentionDays`. The
 * retention sweep purges every archived row on or before this cut-off.
 */
export function retentionCutoff(
  retentionDays: number,
  now: Date = new Date(),
): IsoTimestamp {
  return toIsoTimestamp(new Date(now.getTime() - retentionDays * MS_PER_DAY));
}

/**
 * True once `retentionDays × 24h` have passed since the row was archived. An
 * expired row can no longer be restored, whether or not the sweep has
 * removed it yet.
 */
export function isExpired(
  row: SoftDeletable,
  retentionDays: number,
  now: Date = new Date(),
): boolean {
  if (row.archivedAt === null) return false;
  return (
    now.getTime() - Date.parse(row.archivedAt) >= retentionDays * MS_PER_DAY
  );
}

/** Filters an in-memory collection according to an `ArchiveScope`. */
export function applyArchiveScope<T extends SoftDeletable>(
  rows: readonly T[],
  scope: ArchiveScope = {},
): readonly T[] {
  return scope.includeArchived === true ? rows : rows.filter(isLive);
}

/** True when the repository should add the `archived_at IS NULL` predicate. */
export function shouldFilterArchived(scope: ArchiveScope = {}): boolean {
  return scope.includeArchived !== true;
}

/** The column patch that archives a row. */
export function archivePatch(now: Date = new Date()): {
  archivedAt: IsoTimestamp;
  updatedAt: IsoTimestamp;
} {
  const stamp = toIsoTimestamp(now);
  return { archivedAt: stamp, updatedAt: stamp };
}

/** The column patch that restores an archived row. */
export function restorePatch(now: Date = new Date()): {
  archivedAt: null;
  updatedAt: IsoTimestamp;
} {
  return { archivedAt: null, updatedAt: toIsoTimestamp(now) };
}

export class AlreadyArchivedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly entity: string, readonly id: string) {
    super(`${entity} ${id} is already archived.`);
    this.name = "AlreadyArchivedError";
  }
}

/** Guard for archive actions, so double-archiving is a domain-level conflict. */
export function assertNotArchived(
  entity: string,
  id: string,
  row: SoftDeletable,
): void {
  if (isArchived(row)) {
    throw new AlreadyArchivedError(entity, id);
  }
}

/** Why an archived row could not be brought back. */
export type RestoreRefusalReason =
  | "not_archived"
  | "expired"
  | "project_archived"
  | "quota";

const RESTORE_REFUSAL_MESSAGES: Readonly<Record<RestoreRefusalReason, string>> =
  {
    not_archived: "it is not archived",
    expired: "it has outlived the plan's retention window",
    project_archived: "its project is archived",
    quota: "its project has no room for it under the plan's issue quota",
  };

/** A restore that the domain refuses; like double-archiving, a conflict. */
export class RestoreRefusedError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly reason: RestoreRefusalReason,
    readonly entity: string = "Issue",
    readonly id: string | null = null,
  ) {
    super(
      `${entity}${id === null ? "" : ` ${id}`} cannot be restored: ${RESTORE_REFUSAL_MESSAGES[reason]}.`,
    );
    this.name = "RestoreRefusedError";
  }
}

