s += '''
/**
 * One page of the org's archived issues archived at or before `cutoff`, in id
 * order. `afterId` is the last id of the previous page, so the retention
 * sweep can walk a workspace of any size — every project, archived or not.
 */
export async function listExpiredIssues(
  orgId: OrgId,
  cutoff: IsoTimestamp,
  limit: number,
  afterId: IssueId | null = null,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          isNotNull(issues.archivedAt),
          lte(issues.archivedAt, cutoff),
          afterId === null ? undefined : gt(issues.id, afterId),
        ),
      ),
    )
    .orderBy(asc(issues.id))
    .limit(Math.max(1, limit))
    .all();

  return rows.map((row) => toIssue(row));
}

/** What a purge removed, for the caller to clean up index and quota. */
export interface PurgedIssue {
  readonly issueId: IssueId;
  readonly projectId: ProjectId;
  readonly commentIds: readonly CommentId[];
  readonly attachmentSizes: readonly number[];
}

/**
 * Permanently deletes an issue with its label links, comments and
 * attachments, in one transaction. Before the row goes, the project's
 * high-water mark is raised to its highest number so `nextIssueNumber` never
 * hands a purged number out again. Returns `null` when there is no such row.
 */
export async function purgeIssue(
  orgId: OrgId,
  issueId: IssueId,
): Promise<PurgedIssue | null> {
  return getDb().transaction((tx) => {
    const issue = tx
      .select({ id: issues.id, projectId: issues.projectId })
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .get();
    if (!issue) return null;

    const highest = tx
      .select({ value: sql<number | null>`max(${issues.number})` })
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, issue.projectId),
        ),
      )
      .get();
    const highWater = highest?.value ?? 0;
    const stamp = toIsoTimestamp(new Date());

    tx.insert(issueNumberWatermarks)
      .values({ projectId: issue.projectId, orgId, highWater, updatedAt: stamp })
      .onConflictDoUpdate({
        target: issueNumberWatermarks.projectId,
        set: {
          highWater: sql`max(${issueNumberWatermarks.highWater}, ${highWater})`,
          updatedAt: stamp,
        },
      })
      .run();

    const commentRows = tx
      .select({ id: comments.id })
      .from(comments)
      .where(
        and(orgPredicate(comments.orgId, orgId), eq(comments.issueId, issueId)),
      )
      .all();

    const attachmentRows = tx
      .select({ sizeBytes: attachments.sizeBytes })
      .from(attachments)
      .where(
        and(
          orgPredicate(attachments.orgId, orgId),
          eq(attachments.issueId, issueId),
        ),
      )
      .all();

    tx.delete(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.issueId, issueId),
        ),
      )
      .run();
    tx.delete(comments)
      .where(
        and(orgPredicate(comments.orgId, orgId), eq(comments.issueId, issueId)),
      )
      .run();
    tx.delete(attachments)
      .where(
        and(
          orgPredicate(attachments.orgId, orgId),
          eq(attachments.issueId, issueId),
        ),
      )
      .run();
    tx.delete(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .run();

    return {
      issueId: issue.id as IssueId,
      projectId: issue.projectId as ProjectId,
      commentIds: commentRows.map((row) => row.id as CommentId),
      attachmentSizes: attachmentRows.map((row) => row.sizeBytes),
    };
  });
}
'''
open(p, "w").write(s)
