/**
 * Permanently removes rows archived longer ago than the plan's `retentionDays`.
 *
 * Must call (do not reimplement): getPlanLimits, isArchived
 */
import { getPlanLimits } from "@/config/plan-limits";
import { createLogger } from "@/lib/logger";
import { isArchived, retentionCutoff } from "@/lib/soft-delete";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { IssueId, OrgId } from "@/types/common";

const ORG_BATCH = 25;
const PAGE_SIZE = 100;
const BYTES_PER_MB = 1024 * 1024;

const logger = createLogger("cleanup-archived-job");

/**
 * The retention sweep. Soft-deleted rows are kept for as long as the plan
 * promises and no longer: the cut-off comes from `retentionDays`, so an
 * enterprise tenant keeps years of history where a free one keeps a month.
 *
 * Every issue archived at or before the cut-off has expired out of the trash
 * and is purged for good, in every project of the workspace; the audit rows
 * past the window are purged outright.
 */
export async function runCleanupArchivedJob(now: Date): Promise<JobResult> {
  return runJob("cleanup-archived", async (result) => {
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      const org = await orgRepo.findOrgById(orgId);
      if (!org) continue;

      const { retentionDays } = getPlanLimits(org.plan);
      const cutoff = retentionCutoff(retentionDays, now);

      let afterId: IssueId | null = null;
      for (;;) {
        const expired = await issueRepo.listExpiredIssues(
          orgId,
          cutoff,
          PAGE_SIZE,
          afterId,
        );

        for (const issue of expired) {
          if (!isArchived(issue)) continue;

          try {
            await purgeIssue(orgId, issue.id);
            result.processed += 1;
          } catch (error) {
            result.failed += 1;
            logger.error("issue purge failed", {
              orgId,
              issueId: issue.id,
              reason: error instanceof Error ? error.message : String(error),
            });
          }
        }

        if (expired.length < PAGE_SIZE) break;
        afterId = expired[expired.length - 1]?.id ?? null;
      }

      try {
        const purged = await activityRepo.purgeActivityBefore(orgId, cutoff);
        result.processed += purged;
      } catch (error) {
        result.failed += 1;
        logger.error("activity purge failed", {
          orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

/**
 * Deletes one expired issue with everything hanging off it, drops the search
 * documents of the issue and its comments, and hands the attachments' storage
 * back — each one as its size rounded up to whole megabytes, which is what it
 * was charged. `issuesUsed` is untouched: archived issues are not counted.
 */
async function purgeIssue(orgId: OrgId, issueId: IssueId): Promise<void> {
  const purged = await issueRepo.purgeIssue(orgId, issueId);
  if (!purged) return;

  await searchRepo.deleteSearchDocument(orgId, "issue", purged.issueId);
  for (const commentId of purged.commentIds) {
    await searchRepo.deleteSearchDocument(orgId, "comment", commentId);
  }

  const releasedMb = purged.attachmentSizes.reduce(
    (total, sizeBytes) => total + Math.ceil(sizeBytes / BYTES_PER_MB),
    0,
  );
  if (releasedMb > 0) {
    await usageRepo.incrementUsage(orgId, { storageMbUsed: -releasedMb });
  }
}
EOF

